{"explanation":"For a quadratic \(ax^2+bx+c\), the discriminant \(D=b^2-4ac\) measures how the parabola meets the x-axis. Positive \(D\) gives two crossings, zero gives one tangency, and negative \(D\) gives no real crossings. Use the controls to switch among the three cases.","manimCode":"const title = new Text({ text: 'The discriminant decides the real roots', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.45, 0]);

const formula = new MathTex({ latex: 'D=b^2-4ac' });
await formula.waitForRender();
formula.setColor(YELLOW);
formula.moveTo([0, 2.75, 0]);

const ax = new Axes({
  xRange: [-3, 3, 1],
  yRange: [-1.5, 4, 1],
  xLength: 7.2,
  yLength: 4.5,
  tips: true
});
ax.moveTo([-1.25, -0.55, 0]);

const xLab = new Text({ text: 'x', color: GRAY, fontSize: 20 });
xLab.moveTo([2.55, -2.75, 0]);

const rule = new Text({ text: 'Look for x-axis intersections', color: GRAY, fontSize: 18 });
rule.moveTo([3.95, 1.55, 0]);

scene.add(title, formula, ax, xLab, rule);

let curve;
let rootDots = [];
let info;
let equation;

function removeCurrent() {
  if (curve) scene.remove(curve);
  rootDots.forEach(d => scene.remove(d));
  if (info) scene.remove(info);
  if (equation) scene.remove(equation);
}

function showCase(kind) {
  removeCurrent();
  let fn, eq, message, roots, curveColor;

  if (kind === 'two') {
    fn = x => x * x - 1;
    eq = 'y=x^2-1';
    message = 'D = 4 > 0\\n2 real roots';
    roots = [-1, 1];
    curveColor = BLUE;
  } else if (kind === 'one') {
    fn = x => x * x;
    eq = 'y=x^2';
    message = 'D = 0\\n1 real root (double root)';
    roots = [0];
    curveColor = GREEN;
  } else {
    fn = x => x * x + 1;
    eq = 'y=x^2+1';
    message = 'D = -4 < 0\\n0 real roots';
    roots = [];
    curveColor = RED;
  }

  curve = ax.plot(fn, { color: curveColor, xRange: [-2, 2], numSamples: 180 });
  equation = new Text({ text: eq, color: curveColor, fontSize: 23 });
  equation.moveTo([4.05, 0.8, 0]);
  info = new Text({ text: message, color: WHITE, fontSize: 22 });
  info.moveTo([4.05, 0.05, 0]);

  rootDots = roots.map(r => new Dot({ point: ax.c2p(r, 0), color: YELLOW }));
  scene.add(curve, equation, info, ...rootDots);
}

showCase('two');

const controls = new Controls(scene, { position: 'bottom-right', theme: 'dark', width: 220 });
controls.addButton({ label: 'D > 0: two roots', onClick: () => showCase('two') });
controls.addButton({ label: 'D = 0: one root', onClick: () => showCase('one') });
controls.addButton({ label: 'D < 0: no roots', onClick: () => showCase('zero') });

await scene.wait(999999);"}

